func (r *Resequencer) Add(m Msg) []Msg {        // pending is a msgHeap (heap.Interface)
    r.mu.Lock(); defer r.mu.Unlock()
    heap.Push(&r.pending, m)
    var out []Msg
    for r.pending.Len() > 0 {
        head := r.pending[0]
        if head.Seq != r.expected && time.Now().Before(r.gapUntil) { break }
        out = append(out, heap.Pop(&r.pending).(Msg))   // ordered run
        r.expected, r.gapUntil = head.Seq+1, time.Now().Add(r.gap)
    }
    return out
}
